#include <iostream>
using namespace std;
char findTheDifference(string s, string t) {
    char result=0;
    for(char c: s){
        result^=c;
    }
    for(char c: t){
        result^=c;
    }
    return result;
}
int main(){
    string a= "";
    string b= "";
    cout<<findTheDifference(a,b);
    return 0;
}